  # Two fields on three unequal cells; p0 nodal/quad values have one node/cell.
  values = np.array([[1., 2.], [3., 4.], [5., 6.]])
  ctx = {}
  if value_form is not None:
    ctx.update(basis_type="serendipity",
               poly_order=0,
