    if value_form == "quad":
      ctx.update(quad_rule="gauss", num_quad=1)
  if backend == "gkyl":
    values = gpython.GkylArray.from_numpy(values)
  return pg.GData(ctx=ctx).push([np.array([0., 1., 3., 6.])], values)


